def calculateMonthlyInvoiceTotals(orderHistory, regionCode):
    totals = {}
    for order in orderHistory:
        if order["region"] == regionCode:
            month = order["date"][:7]
            totals[month] = totals.get(month, 0) + order["amount"]
    return totals
